local CatRatePreviewCellNode = Class('CatRatePreviewCellNode')

function CatRatePreviewCellNode:__init()
    self.data = nil
    self.path = nil
end

function CatRatePreviewCellNode:__delete()
    self.data = nil
    self.path = nil
end

function CatRatePreviewCellNode:Awake()
    KTool.SetActive(self.ImgCatballIcon.gameObject, false)
    self.ImgCatballIcon = KTool.GetComponent(self.ImgCatballIcon.gameObject, typeof(RawImage))
    self.__EventCaptureTextureCompleteAction = Events.AddListener(CatHouseCaptureTextureComplete, Bind(self, self.OnEventCaptureTextureCompleteAction))
end

---FreshUI
---@param data MaidCoffeeCatRollConfigVo
function CatRatePreviewCellNode:FreshUI(data)
    self.data = data
    CfUtils.FillText(self.TextName.gameObject, data.name)
    CfUtils.SetUISwitchImage(self.ImgQualityBg.gameObject, data.quality)
end

function CatRatePreviewCellNode:Start()
    ---@type CatEggComponent
    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    local fileNameId = eggComponent:GetFileNameId(MaidCoffeeConstants.BornType.Adult, self.data.catId, self.data.kind1)
    self.fileNameId = fileNameId
    eggComponent:CaptureTexture(MaidCoffeeConstants.BornType.Adult, checkNumber(self.data.catId), self.data.kind1,false, fileNameId)
end

function CatRatePreviewCellNode:OnEventCaptureTextureCompleteAction(id, path)
    if self.fileNameId ~= id then return end
    self.path = path
    ---@type CatEggComponent
    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    local texture = eggComponent:LoadCaptureTexture(path, false)
    self.ImgCatballIcon.texture = texture
    KTool.SetActive(self.ImgCatballIcon.gameObject, true)
end

function CatRatePreviewCellNode:OnDestroy()
    ---@type CatEggComponent
    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    if self.path then
        eggComponent:ClearPath2TextureByPath(false, true, self.path)
    end
    if self.__EventCaptureTextureCompleteAction then
        Events.RemoveListener(CatHouseCaptureTextureComplete, self.__EventCaptureTextureCompleteAction)
        self.__EventCaptureTextureCompleteAction = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return CatRatePreviewCellNode